/**
 * Minimal, dependency-free Markdown renderer for model output.
 *
 * Supports headings, bold/italic, inline code, bullet/numbered lists,
 * blockquotes, horizontal rules and paragraphs. All model text is HTML-escaped
 * first, so nothing generated by the model can inject markup into Zotero's
 * privileged reader document.
 */
(function () {
	const M = globalThis.Moonlit || (globalThis.Moonlit = {});

	function escapeHtml(text) {
		return String(text)
			.replace(/&/g, '&amp;')
			.replace(/</g, '&lt;')
			.replace(/>/g, '&gt;')
			.replace(/"/g, '&quot;')
			.replace(/'/g, '&#39;');
	}

	function inline(text) {
		let out = escapeHtml(text);
		// Math first: the renderer must not touch the sup/sub tags it produces.
		out = out.replace(/\$\$([^$]{1,400})\$\$/g, (match, body) => ` ${M.Latex.renderInline(body)} `);
		out = out.replace(/\$([^$\n]{1,300})\$/g, (match, body) => M.Latex.renderInline(body));
		out = out.replace(/\\\(([\s\S]{1,300}?)\\\)/g, (match, body) => M.Latex.renderInline(body));
		out = out.replace(/`([^`]+)`/g, '<code>$1</code>');
		out = out.replace(/\*\*\*([^*]+)\*\*\*/g, '<strong><em>$1</em></strong>');
		out = out.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
		out = out.replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<em>$2</em>');
		out = out.replace(/(^|[^_])_([^_\n]+)_/g, '$1<em>$2</em>');
		out = out.replace(/~~([^~]+)~~/g, '<del>$1</del>');
		out = out.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<span class="ml-link" data-href="$2">$1</span>');
		return out;
	}

	/**
	 * @param {string} markdown
	 * @param {{compact?: boolean}} [options]
	 * @returns {string} HTML
	 */
	function render(markdown, options = {}) {
		const lines = String(markdown || '').replace(/\r\n?/g, '\n').split('\n');
		const html = [];
		let paragraph = [];
		let listType = null;
		let listItems = [];
		let quoteLines = [];

		const flushParagraph = () => {
			if (paragraph.length) {
				html.push(`<p>${inline(paragraph.join(' '))}</p>`);
				paragraph = [];
			}
		};
		const flushList = () => {
			if (listItems.length) {
				const tag = listType === 'ol' ? 'ol' : 'ul';
				html.push(`<${tag}>${listItems.map(item => `<li>${inline(item)}</li>`).join('')}</${tag}>`);
				listItems = [];
				listType = null;
			}
		};
		const flushQuote = () => {
			if (quoteLines.length) {
				html.push(`<blockquote>${inline(quoteLines.join(' '))}</blockquote>`);
				quoteLines = [];
			}
		};
		const flushAll = () => {
			flushParagraph();
			flushList();
			flushQuote();
		};

		for (const raw of lines) {
			const line = raw.replace(/\s+$/, '');
			if (!line.trim()) {
				flushAll();
				continue;
			}
			const heading = line.match(/^(#{1,6})\s+(.*)$/);
			if (heading) {
				flushAll();
				const level = Math.min(heading[1].length + (options.compact ? 2 : 1), 6);
				html.push(`<h${level} class="ml-h ml-h${heading[1].length}">${inline(heading[2])}</h${level}>`);
				continue;
			}
			if (/^(-{3,}|\*{3,}|_{3,})$/.test(line.trim())) {
				flushAll();
				html.push('<hr/>');
				continue;
			}
			const bullet = line.match(/^\s*[-*+]\s+(.*)$/);
			if (bullet) {
				flushParagraph();
				flushQuote();
				if (listType && listType !== 'ul') {
					flushList();
				}
				listType = 'ul';
				listItems.push(bullet[1]);
				continue;
			}
			const numbered = line.match(/^\s*(\d+)[.)]\s+(.*)$/);
			if (numbered) {
				flushParagraph();
				flushQuote();
				if (listType && listType !== 'ol') {
					flushList();
				}
				listType = 'ol';
				listItems.push(numbered[2]);
				continue;
			}
			const quote = line.match(/^\s*>\s?(.*)$/);
			if (quote) {
				flushParagraph();
				flushList();
				quoteLines.push(quote[1]);
				continue;
			}
			if (listItems.length || quoteLines.length) {
				// Continuation line for the current list item / quote.
				if (listItems.length) {
					listItems[listItems.length - 1] += ` ${line.trim()}`;
				}
				else {
					quoteLines.push(line.trim());
				}
				continue;
			}
			paragraph.push(line.trim());
		}
		flushAll();
		return html.join('');
	}

	/** Strip markdown to plain text (used for copy buttons and caches). */
	function toPlainText(markdown) {
		return String(markdown || '')
			.replace(/```[\s\S]*?```/g, ' ')
			.replace(/`([^`]+)`/g, '$1')
			.replace(/[*_~#>]+/g, '')
			.replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
			.replace(/\n{2,}/g, '\n\n')
			.trim();
	}

	M.Markdown = { render, toPlainText, escapeHtml };
})();
